function getReclaimAiTranslation(key, lang) {
    if (reclaimAiTranslations[lang] && reclaimAiTranslations[lang][key]) {
        return reclaimAiTranslations[lang][key];
    }
    if (reclaimAiTranslations.en && reclaimAiTranslations.en[key]) {
        return reclaimAiTranslations.en[key];
    }
    return null;
}

function applyReclaimAiTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(element => {
        const key = element.getAttribute("data-i18n");
        if (key && (key.startsWith("review.reclaim-ai.") || key.startsWith("review.common.") || key.startsWith("nav."))) {
            const translation = getReclaimAiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

window.addEventListener("languageChanged", (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyReclaimAiTranslations(lang), 200);
});

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : "en";
        applyReclaimAiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : "en";
    applyReclaimAiTranslations(currentLang);
}
